import React, { useState, useContext, useEffect } from "react";
import { Form, InputNumber, Button, Icon, Popover, Radio } from "antd";
import { get } from "lodash";

const EditableContext = React.createContext();

const PREMIUM_SOURCE_MAP = {
  pasarpolis: "pp_premium",
  partner: "partner_premium",
};

export const EditableRow = ({ form, index, ...props }) => (
  <EditableContext.Provider value={form}>
    <tr {...props} />
  </EditableContext.Provider>
);

const EditableCell = (props) => {
  const {
    editable,
    dataIndex,
    title,
    record,
    index,
    handleSave,
    children,
    rowSelection,
    ...restProps
  } = props;

  const [editing, setEditing] = useState(false);
  const form = useContext(EditableContext);

  // Keep the (disabled) edit input in sync with the record. The toolbar's
  // bulk "copy pasarpolis / copy partner" updates custom_premium in the parent
  // tabledata without going through this cell's form, so without this the open
  // input would keep showing the stale pre-copy value.
  useEffect(() => {
    if (editing && form && record) {
      const value = record?.[dataIndex];
      if (value != null && !Number.isNaN(Number(value))) {
        form.setFieldsValue({ [dataIndex]: value });
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editing, record?.[dataIndex]]);

  const toggleEdit = (rec, isSelected) => {
    if (rec && isSelected && !rec.checkbox) {
      rowSelection(rec, isSelected);
    }
    setEditing((prev) => !prev);
  };

  const setData = (source) => {
    const value = Number(get(record, PREMIUM_SOURCE_MAP[source]));
    form.setFieldsValue({ custom_premium: value });
    handleSave({ ...record, custom_premium: value });
  };

  const defaultPremiumSource = () => {
    const current = Number(get(record, dataIndex));
    if (Number.isNaN(current)) return null;
    if (current === Number(get(record, "pp_premium"))) return "pasarpolis";
    if (current === Number(get(record, "partner_premium"))) return "partner";
    return null;
  };

  const SelectionData = (
    <div>
      <Radio.Group
        value={defaultPremiumSource()}
        onChange={(e) => setData(e.target.value)}
        buttonStyle="solid"
      >
        <Radio.Button value="partner">Partner</Radio.Button>
        <Radio.Button value="pasarpolis">Pasarpolis</Radio.Button>
      </Radio.Group>
    </div>
  );

  const Cell = () => {
    return editing && record.checkbox ? (
      <div style={{ display: "flex" }}>
        <Form.Item style={{ margin: 0 }}>
          {form.getFieldDecorator(dataIndex, {
            rules: [
              {
                required: true,
                message: " ",
              },
            ],
            initialValue: record[dataIndex],
          })(
            <InputNumber
              disabled
              placeholder="Use copy button →"
              name={record.unique_key}
              style={{ width: "150px" }}
            />,
          )}
        </Form.Item>
        <Popover content={SelectionData} title="Copy Premium From">
          <Button className="tableButton" shape="circle">
            <Icon type="copy" />
          </Button>
        </Popover>
        <Button
          type="ghost"
          shape="circle"
          size="small"
          onClick={() => toggleEdit()}
          style={{ margin: "6px" }}
        >
          <Icon type="close" />
        </Button>
      </div>
    ) : (
      <div
        className="editable-cell-value-wrap"
        style={{ paddingRight: 24, display: "flex" }}
        onClick={() => toggleEdit(record, true)}
      >
        {children}{" "}
        <Icon type="edit" style={{ cursor: "pointer", padding: "2px" }} />
      </div>
    );
  };

  return <td {...restProps}>{editable ? <Cell /> : children}</td>;
};

export default EditableCell;
