import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Modal, Button, Spin, notification, Table } from 'antd'
import ReconActions from '../../../../../../../redux/recon/actions'
import { get, size } from 'lodash'
import modalTableData from '../../../constants/modalTable'

const { resetReduxStateRecon, postreconResolverSubmit } = ReconActions

class ModalWrapper extends React.Component {
  state = {
    modalDataResolved: { label: 'Resolved' },
    modalDataUnresolved: { label: 'Unresolved' },
    buttonDisabledCheck: true
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      reconresolverfeedbackSubmitMessage
    } = nextProps

    if (reconresolverfeedbackSubmitMessage === 'Success') {
      this.props.closeModal()
      notification.success({ message: 'Success', description: 'Feedback Submitted' })
      this.props.goBack()
      this.props.resetReduxStateRecon(['reconresolverfeedbackSubmitMessage'])
    }
    if (reconresolverfeedbackSubmitMessage !== 'Success' && reconresolverfeedbackSubmitMessage !== undefined) {
      this.props.closeModal()
      notification.error({ message: 'Error', description: reconresolverfeedbackSubmitMessage })
      this.props.resetReduxStateRecon(['reconresolverfeedbackSubmitMessage'])
    }
  }

  componentDidMount () {
    const {
      data
    } = this.props
    if (size(data) > 0) {
      this.setState({
        modalDataResolved: {
          ...this.state.modalDataResolved,
          ...get(data, 'resolved', {})
        },
        modalDataUnresolved: {
          ...this.state.modalDataUnresolved,
          ...get(data, 'unresolved', {})
        }
      })
      const unResolvedData = get(data, 'unresolved', {})
      const { missing_in_pp: missingPP, missing_in_partner: missingPartner, premium_mismatch: premiumMismatch } = unResolvedData
      if (((missingPartner === 0) && (missingPP === 0)) && (premiumMismatch === 0)) {
        this.setState({
          buttonDisabledCheck: false
        })
      }
    }
  }

  handleSubmit = () => {
    const { id } = this.props
    this.props.postreconResolverSubmit({ id: id })
  }

  render () {
    const { buttonDisabledCheck, modalDataResolved, modalDataUnresolved } = this.state
    const { loading } = this.props
    return (
      <Modal
        title='Preview FeedBack Summary'
        visible={this.props.visible}
        // onOk={this.handleOk}
        onCancel={() => this.props.closeModal()}
        footer={[
          <Button type='primary' disabled={buttonDisabledCheck} onClick={this.handleSubmit} key={1}>Submit</Button>
        ]}
      >
        <Spin spinning={loading} tip='Loading...'>
          <>
            <Row type='flex'>
              <Col span={24}>
                <Table
                  columns={modalTableData}
                  dataSource={[modalDataResolved, modalDataUnresolved]}
                  pagination={false}
                />
              </Col>
            </Row>
          </>
        </Spin>
      </Modal>
    )
  }
}

export default connect(
  state => ({
    reconresolverfeedbackSubmitMessage: state.Recon.reconresolverfeedbackSubmitMessage
  }), {
    postreconResolverSubmit,
    resetReduxStateRecon
  }
)(ModalWrapper)
