import { string, number } from 'prop-types'

import { useState } from 'react'
import { SelectAllTableTopWrapper } from './index.style.js'

const SelectAllTableTop = (props) => {
  const [allSelect, setAllSelect] = useState(false)
  const toggleAllSelect = (val) => {
    props.setAllrecords(val)
    setAllSelect(val)
  }
  return (
    <SelectAllTableTopWrapper>
      <span>{allSelect ? props.totalCount : props.pageCount} records {allSelect ? props.selectAction : ''} are selected. </span>
      {!allSelect && <span className='clickable' onClick={() => toggleAllSelect(true)}>Select All {props.totalCount} records in {props.selectAction} </span>}
      {allSelect && <span className='clickable' onClick={() => toggleAllSelect(false)}>Clear selection </span>}
    </SelectAllTableTopWrapper>
  )
}

SelectAllTableTop.prototype = {
  totalCount: number,
  pageCount: number,
  selectAction: string
}

export default SelectAllTableTop
