import { useState, useEffect } from "react";
import { Table, Form } from "antd";
import EditableCell, { EditableRow } from "./editableCell";

const EditableFormRow = Form.create()(EditableRow);

export default function EditableTable({
  loading = false,
  dataSource = [],
  columns = [],
  handleTableChange,
  totalRecords,
  page,
  editableData,
  handleallRowSelected,
  setAllRowSelection,
}) {
  const [loadingState, setLoading] = useState(false);
  const [dataSourceState, setDataSource] = useState([]);
  const [columnsState, setColumns] = useState([]);

  useEffect(() => {
    setLoading(loading);
  }, [loading]);

  useEffect(() => {
    setDataSource(dataSource);
  }, [dataSource]);

  useEffect(() => {
    setColumns(columns);
  }, [columns]);

  const handleSave = (row) => {
    const newData = [...dataSourceState];
    const index = newData.findIndex(
      (item) => row.unique_key === item.unique_key,
    );
    const item = newData[index];
    newData.splice(index, 1, {
      ...item,
      ...row,
    });
    editableData({
      type: "change",
      data: {
        updatedData: newData,
        changeRowIndex: index,
      },
    });
  };

  const onSelectAllRows = (selected, record) => {
    const newRecord = dataSourceState.map((item) => {
      return {
        ...item,
        is_active: selected ? 1 : 0,
        checkbox: selected ? 1 : 0,
      };
    });
    handleallRowSelected(newRecord, selected);
  };

  // Core single-row selection side-effect (mirrors the checkbox toggle).
  const emitSingleToggle = (record, selected) => {
    if (selected === false) {
      setAllRowSelection(false);
    }
    editableData({
      type: "click",
      data: {
        record: {
          ...record,
          is_active: selected ? 1 : 0,
          checkbox: selected ? 1 : 0,
        },
      },
    });
  };

  // Plain checkbox click (antd `onSelect`): toggle a single row.
  const onRowSelection = (record, selected) => {
    emitSingleToggle(record, selected);
  };

  const onSelectMultiple = (checked, selectedRows, changeRows) => {
    if (!changeRows || !changeRows.length) return;
    if (checked === false) {
      setAllRowSelection(false);
    }
    editableData({
      type: "select-rows",
      data: {
        selected: !!checked,
        records: changeRows.map((item) => ({
          ...item,
          checkbox: checked ? 1 : 0,
          is_active: checked ? 1 : 0,
        })),
      },
    });
  };

  const rowKeys = dataSourceState.map((item) =>
    item.checkbox ? item.key : null,
  );
  const components = {
    body: {
      row: EditableFormRow,
      cell: EditableCell,
    },
  };
  const rowSelection = {
    selectedRowKeys: rowKeys,
    getCheckboxProps: (record) => ({
      unique_key: record.unique_key,
    }),
    onSelect: onRowSelection,
    onSelectMultiple: onSelectMultiple,
    onSelectAll: onSelectAllRows,
  };

  const columnsData = columnsState.map((col) => {
    if (!col.editable) {
      return col;
    }
    return {
      ...col,
      onCell: (record) => ({
        record,
        editable: col.editable,
        dataIndex: col.dataIndex,
        title: col.title,
        handleSave: handleSave,
        rowSelection: onRowSelection,
      }),
    };
  });

  return (
    <div className="recon-resolver-table">
      <Table
        rowSelection={rowSelection}
        components={components}
        rowClassName={() => "editable-row"}
        loading={loadingState}
        bordered
        pagination={{
          defaultPageSize: 100,
          total: totalRecords,
          current: page,
        }}
        dataSource={dataSourceState}
        columns={columnsData}
        onChange={handleTableChange}
      />
    </div>
  );
}
