import React from "react";
import { Button, Icon } from "antd";
import { FieldDataCodes } from "../constants/feedbackDetail";

export default function ChooseActionComponent(props) {
  const {
    value,
    actionFunction,
    selectedFields,
    buttonLoading,
    buttonAction,
    showSelectAllActions,
  } = props;
  switch (value) {
    case FieldDataCodes.missing_in_pp:
      return (
        <>
          <Button
            disabled={selectedFields.length === 0}
            onClick={() => actionFunction(value, "create")}
            type="primary"
            loading={buttonLoading && buttonAction === "create"}
          >
            Create Policy <Icon type="issues-close" />
          </Button>
          &nbsp;
          <Button
            disabled={selectedFields.length === 0}
            onClick={() => actionFunction(value, "ignore")}
            type="ghost"
            loading={buttonLoading && buttonAction === "ignore"}
          >
            Ignore Policy <Icon type="stop" />
          </Button>
        </>
      );
    case FieldDataCodes.missing_in_partner:
      return (
        <>
          <Button
            disabled={selectedFields.length === 0}
            onClick={() => actionFunction(value, "cancel")}
            type="danger"
            loading={buttonLoading && buttonAction === "cancel"}
          >
            Cancel Policy <Icon type="close-circle" />
          </Button>
          &nbsp;
          <Button
            disabled={selectedFields.length === 0}
            onClick={() => actionFunction(value, "ignore")}
            type="ghost"
            loading={buttonLoading && buttonAction === "ignore"}
          >
            Ignore Policy <Icon type="stop" />
          </Button>
        </>
      );
    case FieldDataCodes.premium_mismatch:
      if (showSelectAllActions) {
        return (
          <>
            <Button
              disabled={selectedFields.length === 0}
              onClick={() => actionFunction(value, "update_from_partner")}
              type="ghost"
              loading={buttonLoading && buttonAction === "update_partner"}
            >
              Update All Partner Premium <Icon type="issues-close" />
            </Button>{" "}
            &nbsp;
            <Button
              disabled={selectedFields.length === 0}
              onClick={() => actionFunction(value, "update_from_pasarpolis")}
              type="primary"
              loading={buttonLoading && buttonAction === "update_pp"}
            >
              Update All Pasarpolis Premium <Icon type="issues-close" />
            </Button>
          </>
        );
      } else {
        return (
          <Button
            disabled={selectedFields.length === 0}
            onClick={() => actionFunction(value, "update_premium")}
            type="primary"
            loading={buttonLoading}
          >
            Update Premium <Icon type="issues-close" />
          </Button>
        );
      }
    default:
      return null;
  }
}
