import React, { useState, useEffect } from "react";
import FeedBackDetailStyleWrapper from "./index.style";
import { Row, Col, Card, Select, notification, Button, Input } from "antd";
import {
  selectFieldData,
  reconResolverDetailSection,
  tableFieldsMissingInPasarpolis,
  tableFieldsMissingInPartner,
  tableFieldsMissingInPartnerPremium,
  FieldDataCodes,
} from "../constants/feedbackDetail";
import { get, size } from "lodash";
import { connect } from "react-redux";
import ReconActions from "../../../../../redux/recon/actions";
import ChooseActionComponent from "./chooseAction";
import EditableTable from "./components/Table";
import ModalWrapper from "./components/Modal";
import QueryString from "query-string";
import QuerySearchBuilder from "../../../../../../helpers/querySearchBuilder";
import SelectAllTableTop from "./components/SelectAllTableTop";
import BulkPremiumBar from "./components/BulkPremiumBar";

const { Option } = Select;
const { Search } = Input;
const {
  reconResolverUpdate,
  reconResolverDetail,
  resetReduxStateRecon,
  reconResolverUpdateAllRecords,
  searchUniqueRecord,
} = ReconActions;

const FeedBackDetail = (props) => {
  const {
    match,
    history,
    location,
    reconResolverDetailData,
    reconResolverUpdateData,
    reconResolverUpdateAllData,
    reconResolverDetailDataMessage,
    reconResolverUpdateDataMessage,
    reconResolverUpdateAllDataMessage,
    searchReconMessage,
    reconResolverUpdateAllDataStatus,
    searchReconData,
    reconResolverDetailLoading,
    reconResolverUpdateDataLoading,
    reconResolverUpdateAllDataLoading,
    searchReconLoading,
    reconResolverUpdate: reconResolverUpdateAction,
    reconResolverDetail: reconResolverDetailAction,
    resetReduxStateRecon: resetReduxStateReconAction,
    reconResolverUpdateAllRecords: reconResolverUpdateAllRecordsAction,
    searchUniqueRecord: searchUniqueRecordAction,
  } = props;

  const [selectedReconData, setSelectedReconData] = useState({});
  const [tabledata, setTabledata] = useState([]);
  const [selectActionItem, setSelectActionItem] = useState("");
  const [modalShow, setModalShow] = useState(false);
  const [selectedRowsData, setSelectedRowsData] = useState([]);
  const [totalRecords, setTotalRecords] = useState(0);
  const [enabledSaveButton, setEnabledSaveButton] = useState(true);
  const [limit, setLimit] = useState(100);
  const [page, setPage] = useState(1);
  const [modalData, setModalData] = useState({});
  const [offset, setOffset] = useState(0);
  const [allRowSelected, setAllRowSelected] = useState(false);
  const [processAllRecords, setProcessAllRecords] = useState(false);
  const [action, setAction] = useState("");
  const [querySearchState, setQuerySearchState] = useState({});

  const paramId = get(match, "params.id", "");

  const fetch = (payload = { limit: 100, offset: 0 }) => {
    const { offset: payloadOffset, limit: payloadLimit } = payload;
    const offsetNumber = payload.offset;
    const limitSize = payload.limit;
    const queryPage = Number(offsetNumber) || Number(payloadOffset);
    const queryLimit = Number(limitSize) || Number(payloadLimit);
    const finalQuery = {
      ...payload,
      page: get(payload, "page", 1),
      state: get(payload, "state", "missing_in_pp"),
      offset: Number(queryPage),
      limit: queryLimit,
    };
    setPage(Number(get(payload, "page", 1)));
    setQuerySearchState(finalQuery);
    setSelectActionItem(get(payload, "state", "missing_in_pp"));
    setLimit(queryLimit);
    const queryString = QuerySearchBuilder(finalQuery);
    history.push({
      pathname: location.pathname,
      search: queryString,
    });
    reconResolverDetailAction({
      query: {
        ...finalQuery,
        id: paramId,
      },
    });
  };

  // componentDidMount
  useEffect(() => {
    if (paramId) {
      const querySearch = QueryString.parse(location.search);
      if (Object.values(querySearch).length > 0) {
        fetch(querySearch);
      } else {
        fetch();
      }
    } else {
      history.goBack();
    }
    // componentWillUnmount
    return () => {
      localStorage.removeItem("selected-rows");
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // searchReconMessage === 'success'
  useEffect(() => {
    if (searchReconMessage === "success") {
      const tableSearchData = searchReconData.map((item, index) => {
        const selectedItemFound =
          selectedRowsData.find(
            (selectedData) => selectedData.unique_key === item.unique_key,
          ) || {};
        if (size(selectedItemFound) > 0) {
          item = {
            ...selectedItemFound,
            key: index,
            process_data: "",
            checkbox: 1,
          };
        } else {
          item = {
            ...item,
            key: index,
            custom_premium: "",
            process_data: item.state
              ? item.state.split("_").join(" ").toUpperCase()
              : "",
            checkbox: 0,
          };
        }
        return item;
      });
      setTabledata(tableSearchData);
      setTotalRecords(searchReconData.length);
      resetReduxStateReconAction(["searchReconMessage"]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchReconMessage]);

  // reconResolverUpdateAllDataStatus === 'UPDATE_POLICY'
  useEffect(() => {
    if (reconResolverUpdateAllDataStatus === "UPDATE_POLICY") {
      notification.info({
        message: "Processing...",
        description: reconResolverUpdateAllDataMessage,
        style: {
          color: "#28a745",
        },
      });
      resetReduxStateReconAction(["reconResolverUpdateAllDataStatus"]);
      resetReduxStateReconAction(["reconResolverUpdateAllDataMessage"]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reconResolverUpdateAllDataStatus]);

  // reconResolverDetailDataMessage
  useEffect(() => {
    if (reconResolverDetailDataMessage === "Success") {
      const data = get(reconResolverDetailData, "data.mismatches", []);
      const newTabledata = data.map((item, index) => {
        const selectedItemFound =
          selectedRowsData.find(
            (selectedData) => selectedData.unique_key === item.unique_key,
          ) || {};
        if (size(selectedItemFound) > 0) {
          item = {
            ...selectedItemFound,
            key: index,
            process_data: "",
            checkbox: 1,
          };
        } else {
          item = {
            ...item,
            key: index,
            custom_premium: "",
            process_data: item.state
              ? item.state.split("_").join(" ").toUpperCase()
              : "",
            checkbox: 0,
          };
        }
        return item;
      });
      const newSelectedReconData = get(reconResolverDetailData, "data", {});
      setTabledata(newTabledata);
      setTotalRecords(get(reconResolverDetailData, "meta.total", 0));
      setSelectedReconData(newSelectedReconData);
      resetReduxStateReconAction(["reconResolverDetailDataMessage"]);
    } else if (reconResolverDetailDataMessage !== undefined) {
      notification.error({
        message: "Error",
        description: "Error in loading Feedback Resolver Detail Page!!!",
      });
      resetReduxStateReconAction(["reconResolverDetailDataMessage"]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reconResolverDetailDataMessage]);

  // reconResolverUpdateDataMessage
  useEffect(() => {
    if (reconResolverUpdateDataMessage === "success") {
      notification.info({
        message: "Processed File Status",
        description: `${selectedRowsData.length} entries processed`,
      });
      setSelectedRowsData([]);
      setEnabledSaveButton(false);
      setAllRowSelected(false);
      setProcessAllRecords(false);
      setModalData(get(reconResolverUpdateData, "details", {}));
      const querySearch = {
        page,
        state: selectActionItem,
        offset,
        limit,
      };
      fetch(querySearch);
      resetReduxStateReconAction(["reconResolverUpdateDataMessage"]);
    } else if (
      reconResolverUpdateDataMessage !== undefined &&
      reconResolverUpdateAllDataStatus === undefined
    ) {
      notification.error({
        message: "Error",
        description: reconResolverUpdateDataMessage,
      });
      resetReduxStateReconAction(["reconResolverUpdateDataMessage"]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reconResolverUpdateDataMessage]);

  // reconResolverUpdateAllDataMessage
  useEffect(() => {
    if (reconResolverUpdateAllDataMessage === "success") {
      notification.info({
        message: "Processed File Status",
        description: `${totalRecords} entries processed`,
      });
      setSelectedRowsData([]);
      setEnabledSaveButton(false);
      setAllRowSelected(false);
      setProcessAllRecords(false);
      setModalData(get(reconResolverUpdateAllData, "details", {}));
      const querySearch = {
        page,
        state: selectActionItem,
        offset,
        limit,
      };
      fetch(querySearch);
      resetReduxStateReconAction(["reconResolverUpdateAllDataMessage"]);
    } else if (
      reconResolverUpdateAllDataMessage !== undefined &&
      reconResolverUpdateAllDataStatus === undefined
    ) {
      notification.error({
        message: "Error",
        description: get(reconResolverUpdateAllData, "detail"),
      });
      resetReduxStateReconAction(["reconResolverUpdateAllDataMessage"]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reconResolverUpdateAllDataMessage]);

  const handleSelectHandleChangeHandler = (value) => {
    localStorage.removeItem("selected-rows");
    setTabledata([]);
    setSelectActionItem(value);
    setSelectedRowsData([]);
    setOffset(0);
    setLimit(100);
    setPage(1);
    setAllRowSelected(false);
    setProcessAllRecords(false);
    const payload = {
      id: paramId,
      state: value,
      offset: 0,
      limit: 100,
      page: 1,
    };
    fetch(payload);
  };

  const onHandleCancel = () => {
    setModalShow(false);
  };

  const getActionTypePasapolis = (type) => {
    setAction(type);
    switch (type) {
      case "create":
        return "create_policy";
      case "ignore":
        return "ignore_policy";
      default:
    }
  };

  const getActionTypePartner = (type) => {
    setAction(type);
    switch (type) {
      case "cancel":
        return "cancel_policy";
      case "ignore":
        return "ignore_policy_partner";
      default:
    }
  };

  const patchRequestHandler = (val, actionType) => {
    const mapper = {
      premium_mismatch: "update_premium",
      missing_in_pp: getActionTypePasapolis(actionType),
      missing_in_partner: getActionTypePartner(actionType),
    };
    const payload = [];
    selectedRowsData.forEach((item) => {
      let premiumValue = 0;
      let extraDetails = "";
      if (selectActionItem === "missing_in_partner") {
        premiumValue = get(item, "pp_premium", "");
        extraDetails = "pasarpolis";
      } else if (selectActionItem === "premium_mismatch") {
        premiumValue = get(item, "custom_premium", "");
        extraDetails = "custom_value";
      } else {
        premiumValue = get(item, "partner_premium", "");
        extraDetails = "partner";
      }
      payload.push({
        unique_key: get(item, "unique_key", ""),
        premium: premiumValue,
        extra_details: { type: extraDetails },
      });
    });
    const data = {
      state: mapper[selectActionItem],
      data: payload,
    };
    if (processAllRecords) {
      const payloadAllRecord = {
        state: mapper[selectActionItem],
      };
      if (actionType === "update_from_partner") {
        setAction(actionType);
        payloadAllRecord.premium_type = "partner_premium";
      }
      if (actionType === "update_from_pasarpolis") {
        setAction(actionType);
        payloadAllRecord.premium_type = "pp_premium";
      }
      reconResolverUpdateAllRecordsAction({
        id: paramId,
        body: payloadAllRecord,
      });
    } else {
      reconResolverUpdateAction({ id: paramId, body: data });
    }
  };

  const editableDataFunction = ({ type, data }) => {
    let oldSelectedPayload = [...selectedRowsData];
    if (type === "click") {
      const { record } = data;
      if (
        oldSelectedPayload.some((item) => item.unique_key === record.unique_key)
      ) {
        oldSelectedPayload = oldSelectedPayload.filter(
          (item) => item.unique_key !== record.unique_key,
        );
      } else {
        oldSelectedPayload.push(record);
      }
      const updateTableData = tabledata.map((item) => {
        if (item.unique_key === record.unique_key) {
          return {
            ...record,
          };
        } else {
          return item;
        }
      });
      setTabledata(updateTableData);
      setSelectedRowsData(oldSelectedPayload);
    } else if (type === "select-rows") {
      const { records, selected } = data;
      // Range selection from a shift+checkbox click. `selected` is the target
      // state of the range (antd passes the clicked box's new state): true adds
      // every row in the range, false removes them. Other rows already selected
      // outside the range are preserved.
      const isSelected = selected !== false;
      const byKey = new Map(records.map((item) => [item.unique_key, item]));
      const updateTableData = tabledata.map((item) =>
        byKey.has(item.unique_key) ? { ...byKey.get(item.unique_key) } : item,
      );
      const selectedByKey = new Map(
        oldSelectedPayload.map((item) => [item.unique_key, item]),
      );
      records.forEach((item) => {
        if (isSelected) {
          selectedByKey.set(item.unique_key, { ...item });
        } else {
          selectedByKey.delete(item.unique_key);
        }
      });
      setTabledata(updateTableData);
      setSelectedRowsData([...selectedByKey.values()]);
    } else {
      const { updatedData, changeRowIndex } = data;
      const changedItem = updatedData[changeRowIndex];
      if (changedItem.is_active) {
        if (
          oldSelectedPayload.some(
            (item) => item.unique_key === changedItem.unique_key,
          )
        ) {
          oldSelectedPayload = oldSelectedPayload.map((item) => {
            if (item.unique_key === changedItem.unique_key) {
              item = {
                ...item,
                ...changedItem,
              };
            }
            return item;
          });
        } else {
          oldSelectedPayload.push(changedItem);
        }
        const updateTableData = tabledata.map((item) => {
          if (item.unique_key === changedItem.unique_key) {
            return {
              ...changedItem,
            };
          } else {
            return item;
          }
        });
        setTabledata(updateTableData);
        setSelectedRowsData(oldSelectedPayload);
      }
    }
  };

  const bulkCopyPremium = (sourceField) => {
    const updatedSelected = selectedRowsData.map((item) => ({
      ...item,
      custom_premium: Number(get(item, sourceField, 0)) || 0,
    }));
    const bySelectedKey = new Map(
      updatedSelected.map((row) => [row.unique_key, row.custom_premium]),
    );
    const updatedTable = tabledata.map((item) =>
      bySelectedKey.has(item.unique_key)
        ? { ...item, custom_premium: bySelectedKey.get(item.unique_key) }
        : item,
    );
    setSelectedRowsData(updatedSelected);
    setTabledata(updatedTable);
  };

  const onHandleAllRowSelected = (newRecord, selected) => {
    const selectedData = newRecord.filter((item) => item.checkbox);
    setTabledata(newRecord);
    setSelectedRowsData(selectedData);
    setAllRowSelected(selected);
  };

  const onHandleTableChangeFunction = (pagination) => {
    const { pageSize, current } = pagination;
    const newOffset = (current - 1) * pageSize;
    const finalFilter = {
      ...querySearchState,
      page: current,
      offset: Number(newOffset),
      limit: Number(pageSize),
    };
    setTabledata(props.dataSource);
    setQuerySearchState(finalFilter);
    const queryString = QuerySearchBuilder(finalFilter);
    history.push({
      pathname: location.pathname,
      search: queryString,
    });
    setOffset(newOffset);
    setLimit(Number(pageSize));
    fetch({
      ...finalFilter,
    });
  };

  const goBackToListPage = () => {
    history.push({
      pathname: "/recon/feedback",
    });
  };

  const renderTableColumns = (actionItem) => {
    switch (actionItem) {
      case FieldDataCodes.missing_in_pp:
        return tableFieldsMissingInPasarpolis;
      case FieldDataCodes.missing_in_partner:
        return tableFieldsMissingInPartner;
      case FieldDataCodes.premium_mismatch:
        return tableFieldsMissingInPartnerPremium;
      default:
        return [];
    }
  };

  const handleShowModalHandler = () => {
    setModalShow(true);
  };

  const getActionKeyName = (key) => {
    switch (key) {
      case FieldDataCodes.missing_in_pp:
        return "missing in pasarpolis";
      case FieldDataCodes.missing_in_partner:
        return "missing in partner";
      case FieldDataCodes.premium_mismatch:
        return "premium mismatch";
      default:
        return "";
    }
  };

  const setAllRowSelection = (val) => {
    if (!val) {
      setProcessAllRecords(false);
    }
    setAllRowSelected(val);
  };

  const setAllRecords = (val) => {
    setProcessAllRecords(val);
  };

  const handleSearch = (val) => {
    if (val.trim()) {
      const query = {
        id: paramId,
        unique_key: val.trim(),
        state: selectActionItem,
      };
      searchUniqueRecordAction({ query });
    } else {
      fetch();
    }
  };

  const handleClear = (e) => {
    if (e.type !== "change") {
      if (paramId) {
        const querySearch = QueryString.parse(location.search);
        if (Object.values(querySearch).length > 0) {
          fetch(querySearch);
        } else {
          fetch();
        }
      }
    }
  };

  const querySearch = QueryString.parse(location.search);
  const actionItem =
    selectActionItem === ""
      ? get(querySearch, "state", "missing_in_pp")
      : selectActionItem;
  const showSelectAllTableTop =
    totalRecords > 100 && (allRowSelected || processAllRecords);

  return (
    <FeedBackDetailStyleWrapper>
      {modalShow && (
        <ModalWrapper
          id={paramId}
          loading={
            !!reconResolverUpdateDataLoading ||
            !!reconResolverUpdateAllDataLoading
          }
          visible={modalShow}
          closeModal={onHandleCancel}
          data={modalData}
          goBack={goBackToListPage}
        />
      )}
      <Row type="flex" justify="space-between">
        <Col>
          <Button onClick={() => goBackToListPage()}>Back</Button>
        </Col>
      </Row>
      <Card className="marginT10">
        <Row type="flex">
          <Col span={24}>
            <p className="heading">Resolver Detail Page</p>
          </Col>
        </Row>
        <Row type="flex" justify="space-between">
          {reconResolverDetailSection.map((item, index) => {
            return (
              <Col key={index} span={12} className="marginB10">
                <Row type="flex">
                  <Col>
                    <span>
                      <b>{item.label}</b>
                    </span>
                  </Col>
                </Row>
                <Row type="flex">
                  <Col>
                    <span>{get(selectedReconData, `${item.code}`)}</span>
                  </Col>
                </Row>
              </Col>
            );
          })}
        </Row>
      </Card>
      <Card className="marginT10">
        <Row type="flex" justify="center" align="bottom">
          <Col span={3} offset={3}>
            <p>
              <b>Choose Data</b>
            </p>
            <Select
              defaultValue={actionItem}
              className="select-field"
              placeholder="Select Action..."
              onChange={handleSelectHandleChangeHandler}
            >
              {selectFieldData.map((item, index) => (
                <Option key={index} value={item.code}>
                  {item.showData}
                </Option>
              ))}
            </Select>
          </Col>
          <Col span={7} offset={2}>
            <Search
              placeholder="Search Unique Key"
              enterButton="Search"
              size="medium"
              onSearch={handleSearch}
              allowClear
              onChange={handleClear}
            />
          </Col>
          <Col span={8} offset={1}>
            {actionItem && (
              <>
                <p>
                  <b>Choose Action</b>
                </p>
                <ChooseActionComponent
                  buttonLoading={
                    reconResolverUpdateDataLoading ||
                    reconResolverUpdateAllDataLoading
                  }
                  selectedFields={selectedRowsData}
                  value={actionItem}
                  buttonAction={action}
                  actionFunction={patchRequestHandler}
                  showSelectAllActions={
                    showSelectAllTableTop && processAllRecords
                  }
                />
              </>
            )}
          </Col>
        </Row>
        <Row className="table-row-style" type="flex" justify="center">
          <Col span={18}>
            <Row type="flex" justify="center" align="middle" />
            <br />
            {showSelectAllTableTop && (
              <SelectAllTableTop
                totalCount={totalRecords}
                pageCount={selectedRowsData.length}
                setAllrecords={setAllRecords}
                selectAction={getActionKeyName(selectActionItem)}
              />
            )}
            {actionItem === "premium_mismatch" &&
              selectedRowsData.length > 0 &&
              !processAllRecords && (
                <BulkPremiumBar
                  selectedCount={selectedRowsData.length}
                  onCopyPartner={() => bulkCopyPremium("partner_premium")}
                  onCopyPasarpolis={() => bulkCopyPremium("pp_premium")}
                />
              )}
            <EditableTable
              loading={reconResolverDetailLoading || searchReconLoading}
              columns={renderTableColumns(actionItem)}
              dataSource={tabledata}
              editableData={editableDataFunction}
              handleTableChange={onHandleTableChangeFunction}
              handleallRowSelected={onHandleAllRowSelected}
              totalRecords={totalRecords}
              page={page}
              setAllRowSelection={setAllRowSelection}
              type={getActionKeyName(selectActionItem)}
            />
          </Col>
        </Row>
        <Row type="flex" justify="center">
          <Col className="center-save-button" span={24}>
            <Button
              disabled={enabledSaveButton}
              type="primary"
              onClick={handleShowModalHandler}
            >
              Save
            </Button>
          </Col>
        </Row>
      </Card>
    </FeedBackDetailStyleWrapper>
  );
};

export default connect(
  (state) => ({
    reconResolverDetailData: state.Recon.reconResolverDetailData,
    reconResolverDetailDataMessage: state.Recon.reconResolverDetailDataMessage,
    reconResolverUpdateData: state.Recon.reconResolverUpdateData,
    reconResolverUpdateAllData: state.Recon.reconResolverUpdateAllData,
    reconResolverUpdateAllDataMessage:
      state.Recon.reconResolverUpdateAllDataMessage,
    reconResolverUpdateAllDataStatus:
      state.Recon.reconResolverUpdateAllDataStatus,
    reconResolverUpdateDataMessage: state.Recon.reconResolverUpdateDataMessage,
    reconResolverDetailLoading: state.Loading.RECON_RESOLVER_DETAIL,
    reconResolverDetailError: state.Error.RECON_RESOLVER_DETAIL,
    reconResolverUpdateDataLoading: state.Loading.RECON_RESOLVER_UPDATE,
    reconResolverUpdateDataError: state.Error.RECON_RESOLVER_UPDATE,
    reconResolverUpdateAllDataLoading: state.Loading.RECON_RESOLVER_UPDATE_ALL,
    reconResolverUpdateAllDataError: state.Error.RECON_RESOLVER_UPDATE_ALL,
    searchReconData: state.Recon.searchReconData,
    searchReconMessage: state.Recon.searchReconMessage,
    searchReconLoading: state.Loading.SEARCH_RECON,
    searchReconError: state.Error.SEARCH_RECON,
  }),
  {
    reconResolverUpdate,
    reconResolverDetail,
    resetReduxStateRecon,
    reconResolverUpdateAllRecords,
    searchUniqueRecord,
  },
)(FeedBackDetail);
